import {impactSound} from './sound-events.js?v=25';
import {playSfx} from './sfx.js?v=25';
import {quality} from './quality.js?v=25';
import {cosmicBurst} from './vfx.js?v=25';
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const box=e=>e?.getBoundingClientRect();
export function captureScene(s){if(!s)return {};let orbit=document.querySelector('.meteor-orbit'),matrix=orbit?getComputedStyle(orbit).transform.match(/matrix\(([^)]+)\)/):null,values=matrix?.[1].split(',').map(Number);return {orbitAngle:values?Math.atan2(values[1],values[0])*180/Math.PI:0,deck:box(document.querySelector('.arena [data-pile="draw"] .card')),top:box(document.querySelector('.arena [data-pile="discard"] .top-card .card')),hand:Object.fromEntries([...document.querySelectorAll('[data-card]')].map(e=>[e.dataset.card,box(e)]))};}
function fly(html,from,to,delay=0){if(!from||!to||reduced())return 0;const width=Math.min(from.width,110),targetWidth=Math.min(to.width,142);from={left:from.left+from.width/2-width/2,top:from.top+from.height/2-width*.75,width,height:width*1.5};to={left:to.left+to.width/2-targetWidth/2,top:to.top+to.height/2-targetWidth*.75,width:targetWidth,height:targetWidth*1.5};let e=document.createElement('div');e.setAttribute('aria-hidden','true');e.className='flying-card';e.innerHTML=html;e.style.cssText=`left:${from.left}px;top:${from.top}px;width:${from.width}px;height:${from.height}px`;document.body.append(e);let dx=to.left+to.width/2-from.left-from.width/2,dy=to.top+to.height/2-from.top-from.height/2;
 e.animate([{transform:'translate(0,0) rotate(-8deg)',opacity:1},{transform:`translate(${dx*.5}px,${dy*.5-65}px) rotate(12deg) scale(1.12)`,offset:.5,opacity:1},{transform:`translate(${dx}px,${dy}px) rotate(0deg) scale(${to.width/from.width})`,opacity:.85}],{duration:650,delay,easing:'cubic-bezier(.2,.7,.25,1)',fill:'both'}).finished.finally(()=>e.remove());return 650;}
function sparks(rect,color){if(!rect||reduced())return;for(let i=0;i<16;i++){let e=document.createElement('i');e.className='spark';e.style.cssText=`left:${rect.left+rect.width/2}px;top:${rect.top+rect.height/2}px;background:var(--${color})`;document.body.append(e);let angle=i/16*Math.PI*2,r=60+Math.random()*90;e.animate([{transform:'translate(-50%,-50%) scale(1)',opacity:1},{transform:`translate(${Math.cos(angle)*r}px,${Math.sin(angle)*r}px) rotate(180deg) scale(0)`,opacity:0}],{duration:650,easing:'ease-out'}).finished.finally(()=>e.remove());}}
function shout(text,color){let e=document.createElement('div');e.className='action-shout';e.textContent=text;e.style.setProperty('--effect-color',`var(--${color})`);document.body.append(e);setTimeout(()=>e.remove(),1400);}
export function showTurnArrival(s){if(s?.status!=='playing')return;document.querySelectorAll('.turn-trace,.turn-screen-flash').forEach(e=>e.remove());for(const portrait of document.querySelectorAll(`[data-player="${s.turn}"] .portrait`)){const trace=document.createElement('span');trace.className='turn-trace';trace.setAttribute('aria-hidden','true');trace.innerHTML='<i></i><i></i><i></i><i></i>';portrait.append(trace);setTimeout(()=>trace.remove(),1400);}if(s.me===s.turn){const stage=document.querySelector('.phone-stage');if(stage){const flash=document.createElement('span');flash.className='turn-screen-flash';flash.setAttribute('aria-hidden','true');stage.append(flash);setTimeout(()=>flash.remove(),850);}}}
function transitionEffect(event,after,scene){
 const remaining=Math.max(0,event.until-Date.now());if(!remaining)return;
 if(event.skipped){const player=after.players.find(p=>p.id===event.skipped),notice=document.createElement('div');notice.className='skip-notice';notice.setAttribute('role','status');const symbol=document.createElement('b');symbol.textContent='⊘';const text=document.createElement('span');text.textContent=event.skipped===after.me?'TON TOUR EST SAUTÉ !':(player?.name||'')+' passe son tour';notice.append(symbol,text);document.body.append(notice);setTimeout(()=>notice.remove(),remaining);}
 if(event.type!=='reverse')return;
 const orbit=document.querySelector('.meteor-orbit');if(!orbit)return;
 if(reduced()){shout('SENS INVERSÉ',after.color);return;}
 const old=event.fromDirection,newDirection=event.toDirection,start=scene.orbitAngle||0,duration=Math.min(remaining,1900),peak=start+old*1120,target=(performance.now()+duration)/12000*360*newDirection,end=target+360*Math.round((peak+newDirection*300-target)/360);
 const mirror=orbit.querySelector(':scope > g');if(mirror)mirror.setAttribute('transform',old===-1?'translate(600 0) scale(-1 1)':'');
 orbit.style.animation='none';const transform=a=>`translate(-50%,-50%) rotate(${a}deg)`;
 const animation=orbit.animate([{transform:transform(start),opacity:1,easing:'cubic-bezier(.55,0,.9,.4)'},{transform:transform(start+old*90),opacity:.9,offset:.2,easing:'linear'},{transform:transform(start+old*1000),opacity:.35,offset:.48,easing:'ease-out'},{transform:transform(peak),opacity:.3,offset:.58,easing:'ease-in'},{transform:transform(peak+(end-peak)*.7),opacity:.8,offset:.8,easing:'ease-out'},{transform:transform(end),opacity:1}],{duration,fill:'forwards'});
 const arena=orbit.parentElement,halo=document.createElementNS('http://www.w3.org/2000/svg','svg');halo.classList.add('vortex-halo');halo.setAttribute('viewBox','0 0 600 600');halo.setAttribute('aria-hidden','true');halo.style.width=getComputedStyle(orbit).width;halo.innerHTML='<circle cx="300" cy="300" r="235" fill="none" stroke="var(--active)" stroke-width="15"/><circle cx="300" cy="300" r="235" fill="none" stroke="#fff2c2" stroke-width="3"/>'+(quality()==='low'?'':'<circle cx="300" cy="300" r="248" fill="none" stroke="var(--active)" stroke-width="2" stroke-dasharray="42 12"/>');arena.append(halo);
 halo.animate([{opacity:0,transform:transform(start)+' scale(.94)'},{opacity:.05,offset:.2},{opacity:.95,offset:.48},{opacity:1,offset:.58},{opacity:.3,offset:.82},{opacity:0,transform:transform(end)+' scale(1.04)'}],{duration,easing:'ease-in-out'}).finished.finally(()=>halo.remove());
 setTimeout(()=>{if(mirror?.isConnected)mirror.setAttribute('transform',newDirection===-1?'translate(600 0) scale(-1 1)':'');},duration*.55);
 animation.finished.finally(()=>{if(orbit.isConnected){orbit.style.animation='';orbit.style.animationDelay=`-${((newDirection*end%360+360)%360)/30}s`;}animation.cancel();});
}
export function animateScene(before,after,scene){if(!before)return;if(after.status==='finished'&&before.status!=='finished'){cosmicBurst({left:innerWidth/2,top:innerHeight*.35,width:1,height:1},'lime','win');return;}if(after.status!=='playing')return;
 if(after.transition?.id!==before.transition?.id&&after.transition?.until>Date.now())transitionEffect(after.transition,after,scene);
 let top=document.querySelector('.arena [data-pile="discard"] .top-card .card');
 if(before.status!=='playing'){showTurnArrival(after);const d=document.querySelector('[data-pile="draw"] .card');for(let i=0;i<Math.min(7,Math.floor(56/after.players.length));i++)for(let j=0;j<after.players.length;j++){let p=after.players[j],dest=box(document.querySelector(`[data-player="${p.id}"]`));fly(d?.outerHTML,box(d),dest,(i*after.players.length+j)*45);}return;}
 if(before.top?.id!==after.top?.id){let actor=after.players.find(p=>p.count<(before.players.find(q=>q.id===p.id)?.count??0));let origin=scene.hand?.[after.top.id]||box(document.querySelector(`[data-player="${actor?.id}"]`));const flight=fly(top?.outerHTML,origin,box(top));const impact=impactSound(before,after);playSfx(impact.key,1,flight||0,impact.rate);cosmicBurst(box(top),after.color,after.top.v);let labels={skip:'TOUR SAUTÉ !',reverse:'DEMI-TOUR !','+2':'+2 · AÏE !','+4':'+4 · CHAOS !',wild:'NOUVELLE COULEUR !'};if(labels[after.top.v]&&after.top.v!=='skip')shout(labels[after.top.v],after.color);
 }else {for(const p of after.players){let old=before.players.find(q=>q.id===p.id),n=p.count-(old?.count||p.count);if(n>0){let target=p.id===after.me?box(document.querySelector('.hand')):box(document.querySelector(`[data-player="${p.id}"]`));let html=document.querySelector('.arena [data-pile="draw"] .card')?.outerHTML;for(let i=0;i<Math.min(n,6);i++)fly(html,scene.deck,target,i*90);}}}
 if(before.turn!==after.turn&&!(after.transition?.until>Date.now()))showTurnArrival(after);
 if(before.feed?.[0]?.text!==after.feed?.[0]?.text&&after.feed?.[0]?.text.includes('crie NOVA')){shout('NOVA !','coral');cosmicBurst(box(top),'coral','nova');}
}
